import logging
import sys
import threading
from datetime import datetime
from pathlib import Path


class CustomFormatter(logging.Formatter):
    """自定义日志格式化器"""

    def format(self, record):
        # 获取线程ID
        record.thread_id = threading.get_ident()

        # 格式化时间，精确到毫秒
        dt = datetime.fromtimestamp(record.created)
        record.timestamp = dt.strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]

        # 获取文件名（不含路径）
        record.filename_only = Path(record.pathname).name

        return super().format(record)


class Logger:
    """统一的日志记录器"""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls, name="AstribotROS"):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._initialized = False
        return cls._instance

    def __init__(self, name="AstribotROS"):
        if self._initialized:
            return

        self._initialized = True
        self._logger = logging.getLogger(name)
        self._logger.setLevel(logging.DEBUG)
        self._logger.propagate = False

        # 清除已有的处理器
        self._logger.handlers.clear()

        # 创建控制台处理器
        console_handler = logging.StreamHandler(sys.stdout)
        console_handler.setLevel(logging.DEBUG)

        # 设置格式：[时间][级别][文件名:行号][线程ID] 消息
        formatter = CustomFormatter(
            fmt="[%(timestamp)s][%(levelname)s][%(filename_only)s:%(lineno)d][TID:%(thread_id)d] %(message)s"
        )
        console_handler.setFormatter(formatter)

        self._logger.addHandler(console_handler)

    def debug(self, msg, *args, **kwargs):
        """调试级别日志"""
        self._logger.debug(msg, *args, **kwargs, stacklevel=2)

    def info(self, msg, *args, **kwargs):
        """信息级别日志"""
        self._logger.info(msg, *args, **kwargs, stacklevel=2)

    def warning(self, msg, *args, **kwargs):
        """警告级别日志"""
        self._logger.warning(msg, *args, **kwargs, stacklevel=2)

    def warn(self, msg, *args, **kwargs):
        """警告级别日志（别名）"""
        self.warning(msg, *args, **kwargs)

    def error(self, msg, *args, **kwargs):
        """错误级别日志"""
        self._logger.error(msg, *args, **kwargs, stacklevel=2)

    def critical(self, msg, *args, **kwargs):
        """严重错误级别日志"""
        self._logger.critical(msg, *args, **kwargs, stacklevel=2)

    def fatal(self, msg, *args, **kwargs):
        """致命错误级别日志（别名）"""
        self.critical(msg, *args, **kwargs)

    def set_level(self, level):
        """设置日志级别

        Args:
            level: 日志级别，可以是字符串 ("DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL")
                   或 logging 模块的常量 (logging.DEBUG, logging.INFO 等)
        """
        if isinstance(level, str):
            level = getattr(logging, level.upper())
        self._logger.setLevel(level)
        for handler in self._logger.handlers:
            handler.setLevel(level)

    def add_file_handler(self, filename, level=logging.DEBUG):
        """添加文件处理器

        Args:
            filename: 日志文件路径
            level: 日志级别
        """
        file_handler = logging.FileHandler(filename, encoding="utf-8")
        file_handler.setLevel(level)

        # 文件日志格式
        formatter = logging.Formatter(
            fmt="[%(asctime)s.%(msecs)03d][%(levelname)s][%(filename)s:%(lineno)d][TID:%(thread)d] %(message)s",
            datefmt="%Y-%m-%d %H:%M:%S",
        )
        file_handler.setFormatter(formatter)
        self._logger.addHandler(file_handler)


# 创建全局单例
logger = Logger()
